from taf.fdsw.rc.interfaces.exceptions import OperationFailure


class Security18SP():
    def __init__(self, client):
        self._client = client

    def enable_ssh_service(self, timeout):
        resp = self._client.send(
            method='config.utils.update',
            timeout=timeout,
            parameters={'actServiceAccountSsh': True}
        )
        if resp.status is False:
            raise OperationFailure(resp.error)

    def disable_ssh_service(self, timeout):
        resp = self._client.send(
            method='config.utils.update',
            timeout=timeout,
            parameters={'actServiceAccountSsh': False}
        )
        if resp.status is False:
            raise OperationFailure(resp.error)

    def enable_ethernet_port_security(self, timeout):
        resp = self._client.send(
            method='config.utils.update',
            parameters={'actEthernetSec': True},
            timeout=timeout
        )
        if resp.status is False:
            raise OperationFailure(resp.error)

    def disable_ethernet_port_security(self, timeout):
        resp = self._client.send(
            method='config.utils.update',
            parameters={'actEthernetSec': False},
            timeout=timeout
        )
        if resp.status is False:
            raise OperationFailure(resp.error)
